def _runs(mask):
    """Return half-open ranges of consecutive True values."""
    out = []
    start = None
    for i, value in enumerate(mask + [False]):
        if value and start is None:
            start = i
        elif not value and start is not None:
            out.append((start, i))
            start = None
    return out


def transform(grid):
    g = [list(row) for row in grid]
    h = len(g)
    w = len(g[0]) if h else 0
    if not h or not w:
        return g

    # The picture is a lattice of framed panels separated by zero corridors.
    row_bands = _runs([any(g[r][c] != 0 for c in range(w)) for r in range(h)])
    col_bands = _runs([any(g[r][c] != 0 for r in range(h)) for c in range(w)])

    # Panel interiors are the cells one step inside each panel's frame.  Use
    # these to distinguish the common/neutral panel color from signal colors.
    interior = []
    interior_cells = set()
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            for r in range(r0 + 1, r1 - 1):
                for c in range(c0 + 1, c1 - 1):
                    if g[r][c] != 0:
                        interior.append(g[r][c])
                        interior_cells.add((r, c))
    if not interior:
        return g
    neutral = Counter(interior).most_common(1)[0][0]

    # Matching non-neutral interior marks connect through the zero corridors.
    # Existing panel/frame cells are never overwritten.
    for r in range(h):
        by_color = defaultdict(list)
        for c in range(w):
            if (r, c) in interior_cells and g[r][c] != neutral:
                by_color[g[r][c]].append(c)
        for color, positions in by_color.items():
            if len(positions) >= 2:
                for c in range(min(positions), max(positions) + 1):
                    if g[r][c] == 0:
                        g[r][c] = color

    for c in range(w):
        by_color = defaultdict(list)
        for r in range(h):
            if (r, c) in interior_cells and g[r][c] != neutral:
                by_color[g[r][c]].append(r)
        for color, positions in by_color.items():
            if len(positions) >= 2:
                for r in range(min(positions), max(positions) + 1):
                    if g[r][c] == 0:
                        g[r][c] = color
    return g


